import{_ as i,o as u,c as n,a2 as e}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Kigezo cha Mtu Mwenye Nguvu zaidi cha Kiwangazi","description":"","frontmatter":{},"headers":[],"relativePath":"sw/17-位面至高强者标准.md","filePath":"sw/17-位面至高强者标准.md","lastUpdated":null}'),t={name:"sw/17-位面至高强者标准.md"};function w(k,a,h,m,o,l){return u(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="kigezo-cha-mtu-mwenye-nguvu-zaidi-cha-kiwangazi" tabindex="-1">Kigezo cha Mtu Mwenye Nguvu zaidi cha Kiwangazi <a class="header-anchor" href="#kigezo-cha-mtu-mwenye-nguvu-zaidi-cha-kiwangazi" aria-label="Permalink to &quot;Kigezo cha Mtu Mwenye Nguvu zaidi cha Kiwangazi&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>17</td></tr><tr><td>Moduli</td><td>Sheria za Ulimwengu na Mifumo ya Uozi</td></tr><tr><td>Maneno Muhimu</td><td>Mwenye Nguvu zaidi cha Kiwangazi, Kigezo cha Mtu Mwenye Nguvu, Uanzishaji wa 20%, Kisiwa cha Asili, Jukumu la Mtu Mwenye Nguvu</td></tr></tbody></table><h2 id="_1-ufafanuzi-na-nafasi-ya-mtu-mwenye-nguvu-zaidi-cha-kiwangazi" tabindex="-1">1. Ufafanuzi na Nafasi ya Mtu Mwenye Nguvu zaidi cha Kiwangazi <a class="header-anchor" href="#_1-ufafanuzi-na-nafasi-ya-mtu-mwenye-nguvu-zaidi-cha-kiwangazi" aria-label="Permalink to &quot;1. Ufafanuzi na Nafasi ya Mtu Mwenye Nguvu zaidi cha Kiwangazi&quot;">​</a></h2><p>&quot;Mtu Mwenye Nguvu zaidi cha Kiwangazi&quot; ni jina rasmi la utamaduni wa usawa wa Neo kwa waozaji ambao wamefikia kiwango cha nguvu ya ulimwengu, na inamaanisha waozaji wa juu kabisa ambao nguvu zao za kutosha kutoa msaada huru kwa utulivu wa sheria ya kiwangazi kimoja na wanaweza kuleta ushawishi kwa kiwango cha ulimwengu. Katika kigezo cha kugawanya viwango vya umoja, Mtu Mwenye Nguvu zaidi cha Kiwangazi unalingana na Kisiwa cha Tisa &quot;Kisiwa cha Asili&quot; na juu yake, na ni kundi la nguvu la juu zaidi katika Heng Yuan Zhou.</p><p>Mtu Mwenye Nguvu zaidi cha Kiwangazi sio tu cheo cha kiwango cha nguvu, bali pia ni nafasi ya jukumu na kitambulisho. Chini ya mfumo wa utamaduni wa usawa, kadiri nguvu inavyozidi, ndivyo jukumu linavyozidi. Mtu Mwenye Nguvu zaidi cha Kiwangazi sio tu mtu aliyefanikiwa katika uozi wa kibinafsi, bali pia ni mlinzi wa utamaduni, mtunzaji wa sheria, na mwendesha njia kwa wanaofuata. &quot;Mkakati wa uanzishaji wa 20%&quot; wa utamaduni wa usawa, lengo lake la msingi ni katika hatua ya awali ya uundwaji wa utamaduni, kuamsha watu 20% wa jumla ya viumbe kufikia kiwango cha Mtu Mwenye Nguvu zaidi cha Kiwangazi, na kuweka msingi wa nguvu kwa kuinuliwa kwa jumla ya ulimwengu.</p><p>Inahitajika kusema maalum kuwa, &quot;Mtu Mwenye Nguvu zaidi cha Kiwangazi&quot; katika utamaduni wa usawa ana tofauti ya msingi na &quot;Bwana wa Kiwangazi&quot; katika enzi ya uwindaji. Bwana wa Kiwangazi katika enzi ya uwindaji alitumia nguvu kuwatumikia utumwa kiwangazi na kuibia rasilimali, na alikuwa mtautwa na mwivi wa kiwangazi; wakati Mtu Mwenye Nguvu zaidi cha Kiwangazi wa utamaduni wa usawa anatumia nguvu kulinda kiwangazi na kuhudumia viumbe wote, na ni mlinzi na mtumishi wa kiwangazi. Tofauti hii ni udhihirisho wa moja kwaonekana wa dhana ya msingi ya kupinga uwindaji ya utamaduni wa usawa katika kiwango cha wataalamu wa nguvu.</p><h2 id="_2-vigezo-vya-tathmini-ya-mtu-mwenye-nguvu-zaidi-cha-kiwangazi" tabindex="-1">2. Vigezo vya Tathmini ya Mtu Mwenye Nguvu zaidi cha Kiwangazi <a class="header-anchor" href="#_2-vigezo-vya-tathmini-ya-mtu-mwenye-nguvu-zaidi-cha-kiwangazi" aria-label="Permalink to &quot;2. Vigezo vya Tathmini ya Mtu Mwenye Nguvu zaidi cha Kiwangazi&quot;">​</a></h2><p>Tathmini ya Mtu Mwenye Nguvu zaidi cha Kiwangazi inatumia &quot;mfumo wa tathmini ya pande nne&quot;, na tu pande zote nne zinapofikia kiwango, mtu anaweza kutambuliwa rasmi kama Mtu Mwenye Nguvu zaidi cha Kiwangazi:</p><table tabindex="0"><thead><tr><th>Upande</th><th>Maudhui ya Tathmini</th><th>Kigezo cha Kutimiza</th><th>Uzito</th></tr></thead><tbody><tr><td>Upande wa Nguvu</td><td>Kisiwa, kiwango cha nishati, uwezo wa udhibiti wa sheria</td><td>Kufikia Kisiwa cha Tisa cha umoja (Kisiwa cha Asili), kuweza kuhamasisha Nguvu ya Asili kwa uhuru</td><td>40%</td></tr><tr><td>Upande wa Tabia</td><td>Ukomavu wa akili, uaminifu wa maadili, msimamo wa kupinga uwindaji</td><td>Kupitia uchunguzi wa maadili wa Mahakama ya Neo, kuthibitisha uaminifu wa kanuni ya kupinga uwindaji na dhana ya usawa</td><td>25%</td></tr><tr><td>Upande wa Mchango</td><td>Mchango kwa mtandao wa usawa, maendeleo ya utamaduni, na maendeleo ya pamoja ya kabila zote</td><td>Thamani ya mchango inafikia kiwango cha juu cha 20% cha utamaduni, na angalau rekodi moja ya mchango wa kiwango cha utamaduni ipo</td><td>20%</td></tr><tr><td>Upande wa Jukumu</td><td>Dhamira na uwezo wa kuchukua jukumu la umma</td><td>Kuwa tayari na kuweza kuchukua jukumu la umma la kiwango cha kiwangazi na juu (kama vile utunzaji wa neo, ulinzi wa utamaduni, n.k.)</td><td>15%</td></tr></tbody></table><p>Muundo wa mfumo wa tathmini ya pande nne unaonyesha dhana ya tathmini ya wataalamu wa nguvu ya utamaduni wa usawa: &quot;kuwa na uwezo na maadili pamoja, na kuweka maadili kwanza&quot;. Nguvu ni msingi tu, na tabia, mchango, na jukumu pia ni vigezo vya muhimu isivyo kutopishwa. Mtu mwenye nguvu lakini tabia mbaya na anakataa kuchukua jukumu, hata kama amefikia kiwango cha nguvu cha Kisiwa cha Asili, hatitatambuliwa kama &quot;Mtu Mwenye Nguvu zaidi cha Kiwangazi&quot;, bali atagawanywa kama &quot;mtu mwenye hatari kubwa&quot; na atakabiliwa na ufuatiliaji na vizuizi vinavyolingana.</p><h2 id="_3-vigezo-vya-maelezo-ya-upande-wa-nguvu" tabindex="-1">3. Vigezo vya Maelezo ya Upande wa Nguvu <a class="header-anchor" href="#_3-vigezo-vya-maelezo-ya-upande-wa-nguvu" aria-label="Permalink to &quot;3. Vigezo vya Maelezo ya Upande wa Nguvu&quot;">​</a></h2><p>Upande wa nguvu ni msingi wa tathmini ya Mtu Mwenye Nguvu zaidi cha Kiwangazi, na vigezo vya maelezo vyake vinajumuisha:</p><h3 id="_3-1-kigezo-cha-kisiwa" tabindex="-1">3.1 Kigezo cha Kisiwa <a class="header-anchor" href="#_3-1-kigezo-cha-kisiwa" aria-label="Permalink to &quot;3.1 Kigezo cha Kisiwa&quot;">​</a></h3><ul><li>Lazima kufikia Kisiwa cha Tisa cha umoja &quot;Kisiwa cha Asili&quot;, na kugusa sheria ya asili ya ulimwengu</li><li>Kuweza kuhamasisha Nguvu ya Asili kwa utulivu, siyo kuhamasisha kwa mujibu wa mlipuko kwa mara nyingine | Njia ya Mtu Binafsi na sheria ya asili ya ulimwengu imeunganishwa kwa kina, na imefikia hali ya &quot;njia ni asili, asili ni njia&quot;</li></ul><h3 id="_3-2-kigezo-cha-nishati" tabindex="-1">3.2 Kigezo cha Nishati <a class="header-anchor" href="#_3-2-kigezo-cha-nishati" aria-label="Permalink to &quot;3.2 Kigezo cha Nishati&quot;">​</a></h3><ul><li>Nishati ya asili iliyohifadhiwa ndani ya mwili inafikia &quot;kiwango cha kiwangazi&quot; — yaani jumla ya nishati inatosha kutoa msaada wa utendaji wa sheria ya msingi ya kiwangazi cha kati</li><li>Usafi wa nishati unafikia zaidi ya 99%, na karibu haina uchafuzi</li><li>Kasi ya urejeshaji wa nishati inafikia &quot;urejeshaji wa papo hapo&quot; — hata baada ya matumizi makubwa katika vita, inaweza kujirejesha hadi hali kamili katika muda mfupi mno</li></ul><h3 id="_3-3-kigezo-cha-udhibiti-wa-sheria" tabindex="-1">3.3 Kigezo cha Udhibiti wa Sheria <a class="header-anchor" href="#_3-3-kigezo-cha-udhibiti-wa-sheria" aria-label="Permalink to &quot;3.3 Kigezo cha Udhibiti wa Sheria&quot;">​</a></h3><ul><li>Kuweza kuhamasisha na kudhibiti Nguvu ya Sheria kwa kiwango cha ulimwengu</li><li>Kuweza kushiriki katika urekebishaji wa dakika na uboreshaji wa sheria za ulimwengu, na kuleta ushawishi wa halisi kwa utendaji wa sheria</li><li>Kuweza kufanya usafiri wa kati ya mazingira na shughuli za uhuru bila msaada wa neo</li><li>Kuweza kuunda ulimwengu kamili na mfumo wa sheria katika nafasi iliyotengwa (uwezo wa Kisiwa cha Uumbaji)</li></ul><h3 id="_3-4-kigezo-cha-aina-ya-maisha" tabindex="-1">3.4 Kigezo cha Aina ya Maisha <a class="header-anchor" href="#_3-4-kigezo-cha-aina-ya-maisha" aria-label="Permalink to &quot;3.4 Kigezo cha Aina ya Maisha&quot;">​</a></h3><ul><li>Aina ya maisha imekamilisha mageuzi ya mwelekeo wa juu, na inaweza kuwepo na kufanya kazi kwa pamoja katika kiwangazi cha nyenzo, safu ya nishati, na eneo la ufahamu</li><li>Karibu kuwa hai milele — mashambulizi na madhara ya kawaida hawezi kuleta tishio la kuua, na nguvu ya kiwango sawa au juu ndiyo inaweza kumdhuru kwa kweli</li><li>Kuweza kuweka alama ya maisha yake mwenyewe kwenye asili ya ulimwengu, na hata mwili wa mwili ukiharibika anaweza kuzaliwa upya kupitia uwekaji wa asili</li></ul><h2 id="_4-vigezo-vya-maelezo-ya-upande-wa-tabia" tabindex="-1">4. Vigezo vya Maelezo ya Upande wa Tabia <a class="header-anchor" href="#_4-vigezo-vya-maelezo-ya-upande-wa-tabia" aria-label="Permalink to &quot;4. Vigezo vya Maelezo ya Upande wa Tabia&quot;">​</a></h2><p>Upande wa tabia ni sehemu ya pekee zaidi katika tathmini ya wataalamu wa nguvu ya utamaduni wa usawa, na pia ni tofauti ya msingi zaidi na enzi ya uwindaji:</p><h3 id="_4-1-msimamo-wa-kupinga-uwindaji" tabindex="-1">4.1 Msimamo wa Kupinga Uwindaji <a class="header-anchor" href="#_4-1-msimamo-wa-kupinga-uwindaji" aria-label="Permalink to &quot;4.1 Msimamo wa Kupinga Uwindaji&quot;">​</a></h3><ul><li>Anatambua na kufanya mazoezi ya kupinga uwindaji kwa msingi, na hajawahi kuwa na rekodi ya uozi wa uwindaji</li><li>Hata katika hali ngumu ya kipekee, hachagui njia ya kuokoa mwenyewe kwa gharama ya kuibia wengine</li><li>Anapinga na kupinga kwa shauku kila aina ya tabia ya uwindaji, na ana ujasiri wa kusema hapana kwa nguvu za uwindaji</li></ul><h3 id="_4-2-dhana-ya-usawa" tabindex="-1">4.2 Dhana ya Usawa <a class="header-anchor" href="#_4-2-dhana-ya-usawa" aria-label="Permalink to &quot;4.2 Dhana ya Usawa&quot;">​</a></h3><ul><li>Anaelewa kwa kina na anatambua dhana ya msingi ya utamaduni ya &quot;usawa wa kabila zote, kuinuliwa kwa ulimwengu&quot;</li><li>Katika uozi wa kibinafsi na mambo ya umma, daima huweka maslahi ya usawa kwanza</li><li>Anashiriki kwa shauku katika ujenzi na utunzaji wa mtandao wa usawa, na ana tayari kushiriki matokeo ya uozi na maarifa yake mwenyewe na viumbe wote</li></ul><h3 id="_4-3-ukomavu-wa-akili" tabindex="-1">4.3 Ukomavu wa Akili <a class="header-anchor" href="#_4-3-ukomavu-wa-akili" aria-label="Permalink to &quot;4.3 Ukomavu wa Akili&quot;">​</a></h3><p>| Hisia zake ziko imara, na hafanyi tabia inayodhuru utamaduni na viumbe wote kwa sababu ya hisia za kibinafsi</p><ul><li>Ana mtazamo mkubwa wa ulimwengu na mtazamo mrefu wa kihistoria, na hafadhili maendeleo ya muda mrefu kwa sababu ya maslahi ya muda mfupi</li><li>Anaweza kubeba shinikizo makubwa na kushindwa, na hana akili imara na thabiti katika hali ngumu</li></ul><h3 id="_4-4-uchunguzi-wa-maadili" tabindex="-1">4.4 Uchunguzi wa Maadili <a class="header-anchor" href="#_4-4-uchunguzi-wa-maadili" aria-label="Permalink to &quot;4.4 Uchunguzi wa Maadili&quot;">​</a></h3><p>Tathmini ya upande wa tabia inatekelezwa na &quot;Kamiti ya Uchunguzi wa Maadili&quot; chini ya Mahakama ya Neo, na njia za uchunguzi zinajumuisha:</p><ul><li>Uchunguzi wa tabia za kihistoria: kuchunguza rekodi zote za tabia muhimu za mtu anayefanya uozi tangu awali</li><li>Skanaingu ya kina ya ufahamu: kwa hiari ya mtu anayefanya uozi, kufanya skanaingu ya kina katika kiwango cha ufahamu, kuthibitisha mawazo yake ya kweli ndani ya moyo</li><li>Jaribio la shinikizo la hali: kuweka hali ngumu ya maadili ya kipekee katika mazingira ya kufanyiwa kazi, na kuzingatia chaguo la mtu anayefanya uozi | Ufuatiliaji wa muda mrefu: kwa wagombea wanaopingana, kufanya ufuatiliaji na tathmini ya muda mrefu kwa miaka kadhaa</li></ul><h2 id="_5-vigezo-vya-maelezo-ya-upande-wa-mchango" tabindex="-1">5. Vigezo vya Maelezo ya Upande wa Mchango <a class="header-anchor" href="#_5-vigezo-vya-maelezo-ya-upande-wa-mchango" aria-label="Permalink to &quot;5. Vigezo vya Maelezo ya Upande wa Mchango&quot;">​</a></h2><p>Upande wa mchango unapima mchango halisi wa mtu anayefanya uozi kwa utamaduni wa usawa na maendeleo ya pamoja ya kabila zote:</p><h3 id="_5-1-aina-za-mchango" tabindex="-1">5.1 Aina za Mchango <a class="header-anchor" href="#_5-1-aina-za-mchango" aria-label="Permalink to &quot;5.1 Aina za Mchango&quot;">​</a></h3><ul><li><strong>Mchango wa Uozi</strong>: athari ya mfano wa uvunjaji wa kisiwa, uumbaji wa mbinu mpya za uozi, ubunifu wa nadharia ya uozi</li><li><strong>Mchango wa Maarifa</strong>: kushiriki kwa umma uzoefu wa uozi, kazi ya elimu na mafunzo, matokeo ya utafiti wa kitaaluma</li><li><strong>Mchango wa Teknolojia</strong>: ubunifu wa teknolojia ya uhandisi wa sheria, uboreshaji wa teknolojia ya tunda la kuzidisha, uboreshaji wa vifaa vya neo</li><li><strong>Mchango wa Huduma</strong>: utunzaji wa neo, utawala wa utamaduni, mwongozo wa mwalimu, uratibuzi wa kati ya kabila</li><li><strong>Mchango wa Mazingira</strong>: urejeshaji wa mazingira ya sayari, uboreshaji wa mzunguko wa nishati ya kiwangazi, ulinzi wa mazingira ya ulimwengu</li><li><strong>Mchango wa Ulinzi</strong>: kupingania tishio za nje, kulinda usalama wa utamaduni, kuokoa maisha katika majanga</li></ul><h3 id="_5-2-ukiasi-wa-mchango" tabindex="-1">5.2 Ukiasi wa Mchango <a class="header-anchor" href="#_5-2-ukiasi-wa-mchango" aria-label="Permalink to &quot;5.2 Ukiasi wa Mchango&quot;">​</a></h3><p>Thamani ya mchango inarekodiwa na kuhesabiwa kiotomatiki na mtandao wa neo, na aina tofauti za mchano zinapewa uzito tofauti kulingana na ushawishi wake na thamani yake. Kigezo cha mchango wa Mtu Mwenye Nguvu zaidi cha Kiwangazi ni &quot;thamani ya mchango inafikia kiwango cha juu cha 20% cha utamaduni&quot;, na inahitaji angalau &quot;mchango wa kiwango cha utamaduni&quot; — yaani mchango ambao umeleta ushawishi mkubwa na wa kina kwa maendeleo ya utamaduni mzima.</p><h2 id="_6-vigezo-vya-maelezo-ya-upande-wa-jukumu" tabindex="-1">6. Vigezo vya Maelezo ya Upande wa Jukumu <a class="header-anchor" href="#_6-vigezo-vya-maelezo-ya-upande-wa-jukumu" aria-label="Permalink to &quot;6. Vigezo vya Maelezo ya Upande wa Jukumu&quot;">​</a></h2><p>Upande wa jukumu unapima dhamira na uwezo wa mtu anayefanya uozi wa kuchukua jukumu la umma:</p><h3 id="_6-1-aina-za-jukumu" tabindex="-1">6.1 Aina za Jukumu <a class="header-anchor" href="#_6-1-aina-za-jukumu" aria-label="Permalink to &quot;6.1 Aina za Jukumu&quot;">​</a></h3><p>Majukumu ya umma ambayo Mtu Mwenye Nguvu zaidi cha Kiwangazi anahitaji kuchukua yanajumuisha:</p><ul><li><strong>Ulinzi wa Neo</strong>: kuwa na jukumu la kulinda na kutunza neo moja au zaidi za kiwango cha juu</li><li><strong>Mshauri wa Utamaduni</strong>: kama mshauri wa kiwango cha juu zaidi cha utamaduni, kushiriki katika maamuzi ya mwelekeo wa maendeleo ya utamaduni</li><li><strong>Urithi wa Mwalimu</strong>: kulea na kuongoza vizazi vijavyo vya waozaji, hasa wataalamu wenye uwezo wa kufikia kisiwa cha juu zaidi</li><li><strong>Ziarat za Kiwangazi</strong>: kufanya ziara za kila mara katika kila kiwangazi, na kufuatilia utulivu wa kiwangazi na hali ya maendeleo ya utamaduni</li><li><strong>Kushughulikia Majanga</strong>: wakati utamaduni unakabiliwa na majanga makubwa (kama vile kuanguka kwa kiwangazi, uvamizi wa nje, n.k.), kuchukua kazi ya msingi zaidi ya kushughulikia</li><li><strong>Kushiriki Sheria</strong>: kushiriki katika urekebishaji wa dakika na uboreshaji wa sheria za ulimwengu, na kuchangia nguvu kwa kuinuliwa kwa jumla ya ulimwengu</li></ul><h3 id="_6-2-njia-ya-kuchukua-jukumu" tabindex="-1">6.2 Njia ya Kuchukua Jukumu <a class="header-anchor" href="#_6-2-njia-ya-kuchukua-jukumu" aria-label="Permalink to &quot;6.2 Njia ya Kuchukua Jukumu&quot;">​</a></h3><p>Mtu Mwenye Nguvu zaidi cha Kiwangazi anaweza, kulingana na maslahi na ujuzi wake mwenyewe, kuchagua aina ya jukumu anayotaka kuchukua kama msingi, lakini hawezi kukataa kabisa kuchukua jukumu la umma. Utamaduni wa usawa unatekeleza &quot;mfumo wa jukumu la wataalamu wa nguvu&quot; — waozaji ambao wamefikia kiwango cha Mtu Mwenye Nguvu zaidi cha Kiwangazi wana jukumu la kutumia sehemu ya nguvu zao kwa mambo ya umma. Muda mahsusi wa jukumu ni kila mwaka kuweka angalau 30% ya muda na nishati kwa jukumu la umma.</p><h2 id="_7-mkakati-wa-uanzishaji-wa-20" tabindex="-1">7. Mkakati wa Uanzishaji wa 20% <a class="header-anchor" href="#_7-mkakati-wa-uanzishaji-wa-20" aria-label="Permalink to &quot;7. Mkakati wa Uanzishaji wa 20%&quot;">​</a></h2><p>&quot;Mkakati wa uanzishaji wa 20%&quot; ni moja ya mikakati ya msingi katika hatua ya awali ya uundwaji wa utamaduni wa usawa wa Neo, na lengo lake ni katika enzi ya kwanza baada ya uundwaji wa utamaduni, kuamsha watu 20% wa jumla ya viumbe kufikia kiwango cha Mtu Mwenye Nguvu zaidi cha Kiwangazi.</p><h3 id="_7-1-malengo-ya-mkakati" tabindex="-1">7.1 Malengo ya Mkakati <a class="header-anchor" href="#_7-1-malengo-ya-mkakati" aria-label="Permalink to &quot;7.1 Malengo ya Mkakati&quot;">​</a></h3><ul><li>Malengo ya muda mfupi (ndani ya miaka 100 baada ya uundwaji wa utamaduni): kuamsha 1% ya viumbe kufikia Kisiwa cha Asili</li><li>Malengo ya muda wa kati (ndani ya miaka 500 baada ya uundwaji wa utamaduni): kuamsha 10% ya viumbe kufikia Kisiwa cha Asili</li><li>Malengo ya muda mrefu (ndani ya miaka 1000 baada ya uundwaji wa utamaduni): kuamsha 20% ya viumbe kufikia Kisiwa cha Asili</li></ul><h3 id="_7-2-msaada-wa-mkakati" tabindex="-1">7.2 Msaada wa Mkakati <a class="header-anchor" href="#_7-2-msaada-wa-mkakati" aria-label="Permalink to &quot;7.2 Msaada wa Mkakati&quot;">​</a></h3><p>Utekelezaji wa mkakati wa uanzishaji wa 20% unategemea masharti yafuatayo ya msaada:</p><ul><li><strong>Kufunguliwa kwa Mifumo ya Mia Tatu</strong>: kutoa viumbe chaguzi nyingi za njia za uozi</li><li><strong>Uenezi wa Teknolojia ya Tunda la Kuzidisha</strong>: kuongezeka kwa mara mia ya tathmini ya uozi kunakuza sana ufanisi wa uozi</li><li><strong>Mchakato wa Mikataba ya Uzalishaji Pamoja</strong>: kutoa msaada wa rasilimali thabiti kwa waozaji</li><li><strong>Mfumo wa Bila ya Kila Mtu Ana Njia</strong>: kuhakikisha kila maisha ina hali ya msingi ya uozi</li><li><strong>Mtandao wa Walimu</strong>: waozaji wa kiwango cha juu wanawaongoza waozaji wa awali, na huongeza kasi ya kulea wataalamu</li></ul><h3 id="_7-3-umuhimu-wa-mkakati" tabindex="-1">7.3 Umuhimu wa Mkakati <a class="header-anchor" href="#_7-3-umuhimu-wa-mkakati" aria-label="Permalink to &quot;7.3 Umuhimu wa Mkakati&quot;">​</a></h3><p>Umuhimu wa mkakati wa uanzishaji wa 20% hauko tu katika kulea idadi kubwa ya wataalamu wa nguvu, bali pia katika:</p><ul><li>Kutoa msingi wa nguvu wa kutosha kwa kuinuliwa kwa jumla ya ulimwengu</li><li>Kuunda kikundi kikubwa cha wataalamu wa nguvu, na kuzuia ukwasi wa nguvu kwa watu binafsi wa nguvu</li><li>Kuunda hali ya utamaduni ya &quot;wataalamu wa nguvu wanaojitokeza mara kwa mara&quot;, na kuhamasisha maisha mengi kujitahidi kufanya uozi</li><li>Kutoa msingi mpana wa wataalamu wa nguvu kwa jamhuri ya kabila zote, na kuhakikisha kila kabila ina mwakilishi wake mwenye nguvu zaidi</li></ul><h2 id="_8-haki-na-matibabu-ya-mtu-mwenye-nguvu-zaidi-cha-kiwangazi" tabindex="-1">8. Haki na Matibabu ya Mtu Mwenye Nguvu zaidi cha Kiwangazi <a class="header-anchor" href="#_8-haki-na-matibabu-ya-mtu-mwenye-nguvu-zaidi-cha-kiwangazi" aria-label="Permalink to &quot;8. Haki na Matibabu ya Mtu Mwenye Nguvu zaidi cha Kiwangazi&quot;">​</a></h2><p>Kama thawabu ya jukumu ambao wamechukua, Mtu Mwenye Nguvu zaidi cha Kiwangazi anafurahia haki na matibabu yafuatayo:</p><ul><li><strong>Kipaumbele cha Rasilimali</strong>: anafurahia kipaumbele cha juu zaidi katika mgawanyo wa rasilimali za uozi</li><li><strong>Haki ya Kushiriki Sheria</strong>: ana haki ya kushiriki katika maamuzi ya urekebishaji wa dakika na uboreshaji wa sheria za ulimwengu</li><li><strong>Haki ya Kuunda Nafasi</strong>: ana haki ya kuunda nafasi au ulimwengu wa huru wa yake mwenyewe</li><li><strong>Haki ya Maamuzi ya Utamaduni</strong>: ana kiti na haki ya kura katika shirika la juu la maamuzi la utamaduni</li><li><strong>Haki ya Usafiri wa Kati ya Mazingira</strong>: anafurahia haki ya kusafiri kwa uhuru katika kila kiwangazi kinachodhibitiwa na utamaduni wa usawa</li><li><strong>Heshima na Uheshimiwa</strong>: anapata heshima na uheshimiwa kutoka kwa utamaduni mzima, na kazi zake zinaandikwa katika vitabu vya historia ya utamaduni</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kigezo cha Mtu Mwenye Nguvu zaidi cha Kiwangazi ni ufafanuzi upya wa dhana ya &quot;mtu mwenye nguvu&quot; kwa utamaduni wa usawa wa Neo. Katika utamaduni wa usawa, mtu mwenye nguvu sio mwivi, sio bwana, sio mtautwa aliyeketi juu, bali ni mlinzi, mtumishi, na mwendesha njia. Upande wa nguvu ni msingi, upande wa tabia ni roho, upande wa mchango ni thamani, na upande wa jukumu ni ujenzi — pande nne zikiunganishwa, ndipo inakuwa &quot;Mtu Mwenye Nguvu zaidi cha Kiwangazi&quot; wa kweli. Lengo la mkakati wa uanzishaji wa 20% sio tu kulea watu 20% wenye nguvu, bali kulea watu 20% walinzi wanaotayarisha kuchukua jukumu kwa usawa wa kabila zote na kuinuliwa kwa ulimwengu. Wakati watu 20% wa viumbe wote wanafikia kiwango cha Mtu Mwenye Nguvu zaidi cha Kiwangazi na wanafanya dhana ya usawa, kuinuliwa kwa jumla ya ulimwengu hakutakuwa tena ndoto ya mbali.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>14-修炼境界统一划分 (Mgawanyo Umoja wa Viwango vya Uozi)</li><li>23-20%激活战略规划 (Mpango wa Mkakati wa Uanzishaji wa 20%)</li><li>19-修炼伦理与边界 (Maadili na Mipaka ya Uozi)</li></ul>',62)])])}const g=i(t,[["render",w]]);export{d as __pageData,g as default};
